import AppKit
import ImageIO
import UniformTypeIdentifiers

func dimensions(_ w:Int,_ h:Int,_ edge:Int)->(Int,Int){let scale=min(1,Double(edge)/Double(max(w,h)));return(max(1,Int(Double(w)*scale)),max(1,Int(Double(h)*scale)))}
func resize(_ url:URL,_ folder:URL,_ edge:Int)throws->String{guard let src=CGImageSourceCreateWithURL(url as CFURL,nil),let image=CGImageSourceCreateThumbnailAtIndex(src,0,[kCGImageSourceCreateThumbnailFromImageAlways:true,kCGImageSourceThumbnailMaxPixelSize:edge,kCGImageSourceCreateThumbnailWithTransform:true]as CFDictionary)else{throw NSError(domain:"Unreadable image",code:1)};let dest=folder.appendingPathComponent(url.deletingPathExtension().lastPathComponent+"-resized.png");if FileManager.default.fileExists(atPath:dest.path){throw NSError(domain:"Output exists: "+dest.lastPathComponent,code:2)};guard let writer=CGImageDestinationCreateWithURL(dest as CFURL,UTType.png.identifier as CFString,1,nil)else{throw NSError(domain:"Cannot create output",code:3)};CGImageDestinationAddImage(writer,image,nil);guard CGImageDestinationFinalize(writer)else{throw NSError(domain:"PNG write failed",code:4)};return dest.lastPathComponent}

@MainActor final class Delegate:NSObject,NSApplicationDelegate{
 var window:NSWindow!;let output=NSTextView();let setting=NSTextField(string:"800")
 func applicationDidFinishLaunching(_ notification:Notification){NSApp.setActivationPolicy(.regular);window=NSWindow(contentRect:NSRect(x:0,y:0,width:900,height:650),styleMask:[.titled,.closable,.resizable],backing:.buffered,defer:false);window.title="Batch Image Resizer";window.isReleasedWhenClosed=false;let root=window.contentView!;let label=NSTextField(labelWithString:"Maximum edge in pixels; preserves aspect ratio. New PNG copies only.");label.frame=NSRect(x:20,y:590,width:850,height:30);root.addSubview(label);setting.frame=NSRect(x:20,y:545,width:520,height:30);root.addSubview(setting);let button=NSButton(title:"Choose images and output folder",target:self,action:#selector(run));button.frame=NSRect(x:560,y:545,width:280,height:30);root.addSubview(button);let scroll=NSScrollView(frame:NSRect(x:20,y:20,width:850,height:500));scroll.autoresizingMask=[.width,.height];scroll.hasVerticalScroller=true;output.isEditable=false;output.font = .monospacedSystemFont(ofSize:14,weight:.regular);output.isVerticallyResizable=true;output.autoresizingMask=[.width];output.textContainer?.widthTracksTextView=true;scroll.documentView=output;root.addSubview(scroll);window.center();window.makeKeyAndOrderFront(nil);NSApp.activate(ignoringOtherApps:true)}
 @objc func run(){do{
guard let edge=Int(setting.stringValue),edge>=16,edge<=8192 else{throw NSError(domain:"Edge must be 16–8192",code:1)};let panel=NSOpenPanel();panel.allowedContentTypes=[.image];panel.allowsMultipleSelection=true;guard panel.runModal() == .OK else{return};let urls=panel.urls;let folder=NSOpenPanel();folder.canChooseFiles=false;folder.canChooseDirectories=true;guard folder.runModal() == .OK,let destination=folder.url else{return};var rows:[String]=[];for url in urls.prefix(100){do{rows.append(try resize(url,destination,edge))}catch{rows.append(url.lastPathComponent+": "+error.localizedDescription)}};output.string=rows.joined(separator:"\n")
}catch{output.string="Error: \(error.localizedDescription)"}}
 func applicationShouldTerminateAfterLastWindowClosed(_ sender:NSApplication)->Bool{true}
}
@main struct LocalApp{@MainActor static func main()throws{if CommandLine.arguments.contains("--self-test"){let d=dimensions(1600,800,400);precondition(d.0==400&&d.1==200);let small=dimensions(100,50,800);precondition(small.0==100&&small.1==50);print("Model checks passed");return};let app=NSApplication.shared;let delegate=Delegate();app.delegate=delegate;app.run()}}
